import { idColumn, tenantColumns, timestampColumns } from "./_shared";

/**
 * One row per successfully imported batch. The unique `(org_id, import_key)`
 * index is what makes an import replay-safe: a refused import never reaches
 * this insert, so retrying a refused key is a first upload, while retrying a
 * key that made it here returns `issue_ids` instead of writing again.
 */
export const issueImportBatches = sqliteTable(
  "issue_import_batches",
  {
    id: idColumn(),
    ...tenantColumns,
    importKey: text("import_key").notNull(),
    projectId: text("project_id").notNull(),
    issueIds: text("issue_ids").notNull(),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("issue_import_batches_org_key_idx").on(
      table.orgId,
      table.importKey,
    ),
  ],
);

export type IssueImportBatchRow = typeof issueImportBatches.$inferSelect;

