/**
 * Bulk issue import: the replay-key lookup and the single transactional
 * write that creates every row of a batch (labels, issues, the join table
 * and the replay record) or none of them.
 */
import { and, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  getDb,
  issueImportBatches,
  issueLabels,
  issues,
  labels,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { parseJsonArray, toIssue } from "./_mappers";
import type { ImportIssueRowInput } from "@/schemas/issue-import";
import type {
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue } from "@/types/issue";

export type ImportBatch = {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
};

export async function findImportBatch(
  orgId: OrgId,
  importKey: string,
): Promise<ImportBatch | null> {
  const row = getDb()
    .select()
    .from(issueImportBatches)
    .where(
      and(
        orgPredicate(issueImportBatches.orgId, orgId),
        eq(issueImportBatches.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  return {
    projectId: row.projectId as ProjectId,
    issueIds: parseJsonArray<IssueId>(row.issueIds),
  };
}

export type CommitImportParams = {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly startNumber: number;
  readonly rows: readonly ImportIssueRowInput[];
  readonly assigneeIds: readonly (UserId | null)[];
};

/**
 * Writes the whole batch in one SQLite transaction: missing labels are
 * created at most once each, every row becomes an issue numbered in file
 * order, and the replay record is inserted last so a mid-batch failure
 * leaves nothing behind — including no label that would otherwise dangle
 * with no issue using it.
 */
export async function commitImport(
  params: CommitImportParams,
): Promise<readonly Issue[]> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const existingLabels = tx
      .select()
      .from(labels)
      .where(orgPredicate(labels.orgId, params.orgId))
      .all();
    const labelIdByName = new Map<string, LabelId>(
      existingLabels.map((row) => [row.name, row.id as LabelId]),
    );

    const inserted: Issue[] = [];

    params.rows.forEach((row, index) => {
      const rowLabelIds: LabelId[] = [];
      const seen = new Set<string>();
      for (const name of row.labels) {
        if (seen.has(name)) continue;
        seen.add(name);

        let labelId = labelIdByName.get(name);
        if (labelId === undefined) {
          const created = tx
            .insert(labels)
            .values({
              id: newId(),
              orgId: params.orgId,
              name,
              color: "#94a3b8",
              description: null,
              createdAt: stamp,
              updatedAt: stamp,
            })
            .returning()
            .get();
          labelId = created.id as LabelId;
          labelIdByName.set(name, labelId);
        }
        rowLabelIds.push(labelId);
      }

      const issueId = newId();
      const issueRow = tx
        .insert(issues)
        .values({
          id: issueId,
          orgId: params.orgId,
          projectId: params.projectId,
          number: params.startNumber + index,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: params.authorId,
          assigneeId: params.assigneeIds[index] ?? null,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      if (rowLabelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            rowLabelIds.map((labelId) => ({
              orgId: params.orgId,
              issueId,
              labelId,
            })),
          )
          .run();
      }

      inserted.push(toIssue(issueRow, rowLabelIds));
    });

    tx.insert(issueImportBatches)
      .values({
        id: newId(),
        orgId: params.orgId,
        importKey: params.importKey,
        projectId: params.projectId,
        issueIds: JSON.stringify(inserted.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return inserted;
  });
}

