/**
 * Bulk import: same gates as `createIssue`, applied to the whole batch. A
 * replayed `importKey` short-circuits after the access checks and returns the
 * first import's result untouched; otherwise the plan's per-project quota and
 * the workspace's issue-creation rate allowance are both checked for the
 * batch before a single row is written, and the write itself — label
 * creation, every issue, the replay record — happens in one transaction.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const existing = await issueImportRepo.findImportBatch(
    input.orgId,
    input.importKey,
  );
  if (existing) {
    const issues = await issueRepo.findIssuesByIds(
      input.orgId,
      existing.issueIds,
    );
    return {
      importKey: input.importKey,
      projectId: existing.projectId,
      issues,
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assigneeIds = await resolveImportAssignees(input.orgId, input.rows);
  const startNumber = await issueRepo.nextIssueNumber(
    input.orgId,
    input.projectId,
  );

  const issues = await issueImportRepo.commitImport({
    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    authorId: actor.userId,
    startNumber,
    rows: input.rows,
    assigneeIds,
  });

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds: issues.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues,
    replayed: false,
  };
}

/**
 * `assigneeEmail` matches case-insensitively against the workspace's current
 * active members only; anything else — unknown, another workspace's member,
 * or a removed one — leaves the row unassigned rather than erroring.
 */
async function resolveImportAssignees(
  orgId: OrgId,
  rows: readonly ImportIssueRowInput[],
): Promise<readonly (UserId | null)[]> {
  const cache = new Map<string, UserId | null>();
  const resolved: (UserId | null)[] = [];

  for (const row of rows) {
    if (row.assigneeEmail === null) {
      resolved.push(null);
      continue;
    }

    if (!cache.has(row.assigneeEmail)) {
      const user = await userRepo.findUserByEmail(row.assigneeEmail);
      const member = user ? await memberRepo.findMember(orgId, user.id) : null;
      cache.set(
        row.assigneeEmail,
        member && member.status === "active" ? member.userId : null,
      );
    }

    resolved.push(cache.get(row.assigneeEmail) ?? null);
  }

  return resolved;
}

