cat > /tmp/import-smoke.test.ts << 'EOF'
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import * as issueService from "@/server/services/issue-service";
import * as memberRepo from "@/server/repositories/member-repository";
import { createTenant, useTemporaryDatabase } from "../tests/server/_support/fixtures";
import type { Tenant } from "../tests/server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("importsmoke");
});

afterAll(() => cleanup());

describe("importIssues smoke", () => {
  it("imports, replays, resolves assignee/labels, emits event", async () => {
    const seen: unknown[] = [];
    const off = subscribe("issues.imported", (p) => seen.push(p));

    const adminMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);

    const input = {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      importKey: "import-key-001",
      rows: [
        {
          title: "First imported issue",
          description: null,
          status: "backlog" as const,
          priority: "high" as const,
          assigneeEmail: `admin@importsmoke.test`,
          labels: ["bug", "urgent", "bug"],
          dueAt: null,
        },
        {
          title: "Second imported issue",
          description: "desc",
          status: "todo" as const,
          priority: "none" as const,
          assigneeEmail: "nobody@nowhere.test",
          labels: [],
          dueAt: null,
        },
      ],
    };

    const result = await issueService.importIssues(tenant.actors.member, input);
    expect(result.replayed).toBe(false);
    expect(result.issues).toHaveLength(2);
    expect(result.issues[0]?.title).toBe("First imported issue");
    expect(result.issues[0]?.assigneeId).toBe(adminMember?.userId);
    expect(result.issues[0]?.labelIds).toHaveLength(2);
    expect(result.issues[1]?.assigneeId).toBeNull();
    expect(result.issues[0]!.number + 1).toBe(result.issues[1]!.number);
    expect(seen).toHaveLength(1);

    const replay = await issueService.importIssues(tenant.actors.member, {
      ...input,
      rows: [{ ...input.rows[0]!, title: "Different title now" }],
    });
    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((i) => i.id)).toEqual(result.issues.map((i) => i.id));
    expect(seen).toHaveLength(1);

    off();
  });
});
EOF
